# ============================================
# GROUPED METRIC COMBOBOX
# ============================================

def create_grouped_metric_combobox(parent, variable, width=35):
    """
    Create a combobox with grouped metric categories.
    Group headers are non-selectable.
    
    Parameters:
    -----------
    parent : tkinter widget
        The parent widget
    variable : tk.StringVar
        The variable to store the selected metric
    width : int
        Width of the combobox
    
    Returns:
    --------
    tuple: (combobox, metric_groups_dict)
    """
    
    # Define groups with their metrics
    metric_groups = {
        '─── Environment ───': [
            'air_temp',
            'saturating_air_humidity',
            'absorbed_radiation',
            'relative_air_humidity',
            'VPD',
            'rad_ind_leaf_temp_increase',
        ],
        '─── Temperature ───': [
            'leaf_temp_c',
            'transp_ind_leaf_temp_depr',
        ],
        '─── CO2 Exchange ───': [
            'CO2_exchange_rate',
            'P_gross',                      
            'R_dark_estimate',              
        ],
        '─── Transpiration ───': [
            'Transpiration_H2O_evol_rate',
        ],
        '─── Conductances ───': [
            'overall_conductance',
            'corr_d_overall_conductance',
            'b_layer_conductance',
            'corr_leaf_conductance',
            'corr_stomatal_conductance',
            'Stomatal_conductance_corrected',
            'normalised_corr_stomatal_conductance',
            'corr_stomatal_change_rate',
            'relat_stom_cond_change_rate',
            'stomatal_sensitivity_vpd',     
        ],
        '─── Ozone ───': [
            'overall_O3_uptake_rate_c',
            'corr_conductance_for_O3_c',
            'corr_stomatal_O3_uptake_rate',
            'corr_cumul_O3_dose',
            'ozone_sensitivity_index',      
        ],
        '─── CO2 Dynamics ───': [
            'massflow_corr_d_ca',
            'massflow_corr_for_CO2',
            'mflowcorr_Ca_gradient',
            'stom_resist_to_CO2',
            'b_layer_resist_to_CO2',
            'corr_ted_CO2_grad',
            'intercell_CO2_conc_in_gas_phase',
            'uncorr_ci',
            'corr_uncorr_ci',
            'Ca_CI_gradient',               
            'stomatal_limitation',          
        ],
        '─── Mesophyll ───': [
            'mesophyll_conductance_for_CO2',
            'uncorr_gm_prima',
            'corr_uncorr_gm_prima',
            'CO2_comp_point',
            'uncorr_gamma',
            'corr_uncorr_gamma',
            'carboxylation_efficiency',     
            'V_cmax_approx',                
            'electron_transport_rate_approx', 
        ],
        '─── Efficiency ───': [
            'WUEi',
            'WUE',
            'WUE_gross',                    
            'WUEi_gross',                   
            'WUE_vcmax',                    
        ],
        '─── Vapor Pressure ───': [
            'saturation_vapor_pressure_inside_leaves',
            'vapor_pressure_around_leaves',
            'mean_vapor_pressure',
            'leaf_air_hum_grad',
            'satur_hum_at_leaf_temp_c',
        ],
    }
    
    # Create flat list with group headers as separators
    display_items = []
    for group, metrics in metric_groups.items():
        display_items.append(group)  # Group header (non-selectable)
        display_items.extend(metrics)
    
    # Create combobox
    combo = ttk.Combobox(parent, values=display_items, width=width)
    
    # Set initial value if the current variable value exists in the list
    current_value = variable.get()
    if current_value in display_items:
        combo.set(current_value)
    else:
        # Try to find the metric in any group
        all_metrics = []
        for metrics in metric_groups.values():
            all_metrics.extend(metrics)
        if current_value in all_metrics:
            combo.set(current_value)
        else:
            combo.set(display_items[0])  # Default to first item
    
    # Store reference to groups for validation
    combo.metric_groups = metric_groups
    
    # Custom behavior: prevent selecting group headers
    def on_select(event):
        selected = combo.get()
        # Check if selected is a group header (starts with ───)
        if selected.startswith('───'):
            # Reset to previous valid selection
            combo.set(variable.get())
            return
        variable.set(selected)
    
    combo.bind('<<ComboboxSelected>>', on_select)
    
    # Also validate on manual entry
    def validate_entry():
        value = combo.get()
        if value.startswith('───'):
            combo.set(variable.get())
            return
        # Check if value is in any group
        all_metrics = []
        for metrics in metric_groups.values():
            all_metrics.extend(metrics)
        if value in all_metrics:
            variable.set(value)
    
    combo.bind('<FocusOut>', lambda e: validate_entry())
    
    return combo, metric_groups
  
