    def run_llm_analysis(self):
        """Run LMM analysis on selected metric with automatic light-dark detection"""
        if not hasattr(self, 'batch_all_processed_data') or not self.batch_all_processed_data:
            messagebox.showwarning("Warning", "No batch data available. Run batch processing first.")
            return

        # Get the metric and alpha level
        metric = self.llm_metric_var.get()
        try:
            alpha = float(self.llm_alpha_var.get())
            if alpha <= 0 or alpha >= 1:
                raise ValueError("Alpha must be between 0 and 1")
        except ValueError:
            messagebox.showerror("Error", "Please enter a valid alpha level (e.g., 0.05)")
            return

        # ============ CHECK CHANNEL SELECTION ============
        if hasattr(self, 'batch_channel_vars') and self.batch_channel_vars:
            selected_channels = [ch for ch, var in self.batch_channel_vars.items() if var.get()]
            if not selected_channels:
                messagebox.showwarning("Warning", 
                    "No channels selected.\n\n"
                    "Please select at least one channel in the Metric Plots tab\n"
                    "before running the LMM analysis.")
                self.llm_status_label.config(text="No channels selected", foreground="orange")
                return
        else:
            messagebox.showwarning("Warning", 
                "Channel selection not available.\n\n"
                "Please run batch processing first.")
            self.llm_status_label.config(text="No channel selection available", foreground="orange")
            return

        # Combine all processed data
        combined_df = pd.concat(self.batch_all_processed_data, ignore_index=True)

        # Ensure we have the required columns
        if 'replicate' not in combined_df.columns:
            if hasattr(self, 'batch_file_paths') and self.batch_file_paths:
                for i, filepath in enumerate(self.batch_file_paths):
                    filename = os.path.basename(filepath)
                    rep_match = re.search(r'(Rep\d+)', filename, re.IGNORECASE)
                    if rep_match:
                        combined_df.loc[combined_df['replicate'] == f'File_{i}', 'replicate'] = rep_match.group(0)
            else:
                combined_df['replicate'] = combined_df.groupby('Channel').cumcount().astype(str)

        # Apply base name extraction to Channel column
        combined_df['Channel'] = combined_df['Channel'].astype(str).str.replace(r'\s*\(\d+\)$', '', regex=True)

        # Filter by selected channels
        combined_df = combined_df[combined_df['Channel'].isin(selected_channels)]

        if len(combined_df) == 0:
            messagebox.showwarning("Warning", "No data available for the selected channels.")
            self.llm_status_label.config(text="No data for selected channels", foreground="red")
            return

        # Check if the metric exists
        if metric not in combined_df.columns:
            messagebox.showerror("Error", f"Metric '{metric}' not found in the data.")
            self.llm_status_label.config(text=f"Metric not found", foreground="red")
            return

        # Check if this is a light-dark experiment (has absorbed_radiation column)
        is_light_dark = 'absorbed_radiation' in combined_df.columns

        # Update status
        self.llm_status_label.config(text=f"Running LMM analysis... (Light-Dark: {is_light_dark})", foreground="orange")
        self.root.update()

        # Enable text widget for writing
        self.llm_results_text.config(state='normal')
        self.llm_results_text.delete(1.0, tk.END)
        self.llm_results_text.insert(tk.END, f"Running Linear Mixed Model analysis...\n")
        self.llm_results_text.insert(tk.END, f"Selected channels: {', '.join(selected_channels)}\n")
        self.llm_results_text.insert(tk.END, f"Light-Dark detection: {'Enabled' if is_light_dark else 'Disabled'}\n\n")
        self.llm_results_text.update()

        try:
            # Run the appropriate analysis
            if is_light_dark:
                self.llm_results_text.insert(tk.END, "Light-dark experiment detected. Using phase-specific LMM.\n\n")
                results = self.llm_analyzer.run_light_dark_lmm(
                    combined_df, 
                    metric=metric, 
                    alpha=alpha
                )
            else:
                self.llm_results_text.insert(tk.END, "Standard LMM analysis (no light-dark detection).\n\n")
                results = self.llm_analyzer.run_linear_mixed_model(
                    combined_df, 
                    metric=metric, 
                    alpha=alpha
                )
    
            # Store results for later use
            self.current_llm_results = results
    
            # Format and display results
            formatted_results = self.llm_analyzer.format_results_for_display(results)
            self.llm_results_text.delete(1.0, tk.END)
            self.llm_results_text.insert(tk.END, formatted_results)
    
            # ============ GENERATE DIAGNOSTIC PLOTS ============
            # Get the model for diagnostics
            model_to_use = results.get('model_for_diagnostics', None)

            # Also try to get the phase model if full model not available
            if model_to_use is None and is_light_dark:
                model_to_use = results.get('model_phase', None)
                # If still None, try the light phase model
                if model_to_use is None:
                    model_to_use = results.get('phase_effects', {}).get('light', {}).get('model', None)

            if model_to_use is not None:
                self.llm_status_label.config(text="Generating diagnostic plots...", foreground="orange")
                self.root.update()

                # Get the LMM data
                lmm_df = results.get('_lmm_data', None)
                if lmm_df is None:
                    # Try to prepare data again
                    lmm_df = self.llm_analyzer.prepare_balanced_lmm_data(
                        combined_df, 
                        metric=metric,
                        time_col='time_repeated',
                        group_col='replicate',
                        line_col='Channel',
                        detect_darkness=is_light_dark
                    )

                if lmm_df is not None and len(lmm_df) > 0:
                    palette = self.batch_palette_var.get() if hasattr(self, 'batch_palette_var') else 'tab10'

                    # Store analysis type for plot title
                    self.llm_analyzer.current_analysis_type = results.get('analysis_type', 'LMM')

                    # IMPORTANT: Close any existing figures before creating new ones
                    plt.close('all')

                    fig = self.generate_llm_diagnostic_plots(
                        lmm_df, model_to_use, metric, palette
                    )

                    if fig is not None:
                        self.display_diagnostic_plots(fig)
                        self.llm_results_text.insert(tk.END, "\n\n" + "=" * 70 + "\n")
                        self.llm_results_text.insert(tk.END, "✅ Diagnostic plots generated and displayed in the 'LMM Diagnostic Plots' tab.\n")
                    else:
                        self.llm_results_text.insert(tk.END, "\n\n Could not generate diagnostic plots - model may not have residuals.\n")
                        self.llm_results_text.insert(tk.END, "Try running the analysis with a different metric or check the data.\n")
                else:
                    self.llm_results_text.insert(tk.END, "\n\n Could not prepare data for diagnostic plots.\n")
            else:
                self.llm_results_text.insert(tk.END, "\n\n No valid model found for diagnostic plots. Check the analysis results above.\n")
                # Show available keys for debugging
                available_keys = [k for k in results.keys() if not k.startswith('_')]
                if available_keys:
                    self.llm_results_text.insert(tk.END, f"Available result keys: {', '.join(available_keys[:10])}\n")
        
            # Update status
            if 'error' in results and results['error']:
                self.llm_status_label.config(text=f"Analysis completed with warnings", foreground="orange")
            else:
                phase_sig = results.get('fixed_effects', {}).get('phase_test', {}).get('significant', False)
                interaction_sig = results.get('fixed_effects', {}).get('line_phase_interaction', {}).get('significant', False)
        
                if phase_sig or interaction_sig:
                    self.llm_status_label.config(text=f"Analysis complete - Significant effects found", foreground="green")
                else:
                    self.llm_status_label.config(text=f"Analysis complete", foreground="blue")

        except Exception as e:
            self.llm_results_text.delete(1.0, tk.END)
            self.llm_results_text.insert(tk.END, f"Error running LMM analysis:\n\n{str(e)}\n\n")
            self.llm_results_text.insert(tk.END, traceback.format_exc())
            self.llm_status_label.config(text=f"Error: {str(e)}", foreground="red")
            traceback.print_exc()

        self.llm_results_text.config(state='disabled')

    def generate_llm_diagnostic_plots(self, lmm_df, model_results, metric, palette='tab10'):
        """
        Generate diagnostic plots for the LMM/OLS analysis and display them in the GUI.
        Handles both mixed models and OLS models.
        """
        if model_results is None:
            print("No model results available for diagnostic plots")
            return None

        # Check if model_results has the required attributes
        if not hasattr(model_results, 'fittedvalues') or not hasattr(model_results, 'resid'):
            print("Model results missing fittedvalues or resid attributes")
            # Try to create residuals from the data if possible
            if hasattr(model_results, 'params') and lmm_df is not None:
                try:
                    print("Attempting to calculate residuals from model parameters...")
                    from statsmodels.formula.api import ols
                    if 'Line' in lmm_df.columns and 'Time_centered' in lmm_df.columns:
                        # Re-fit OLS to get residuals
                        model_ols = ols("Response ~ C(Line) * Time_centered", data=lmm_df).fit()
                        model_results = model_ols
                        print(" Re-fitted OLS model for diagnostics")
                    else:
                        return None
                except Exception as e:
                    print(f"Could not re-fit model: {e}")
                    return None
            else:
                return None

        # Helper function to get colors based on palette
        def get_palette_colors(n_colors):
            try:
                if palette in colorblind_friendly_palettes:
                    if isinstance(colorblind_friendly_palettes[palette], list):
                        color_list = colorblind_friendly_palettes[palette]
                        colors = [color_list[i % len(color_list)] for i in range(n_colors)]
                    else:
                        cmap = colorblind_friendly_palettes[palette]
                        colors = cmap(np.linspace(0, 1, n_colors))
                elif palette in plt.colormaps():
                    cmap = plt.get_cmap(palette)
                    colors = cmap(np.linspace(0, 1, n_colors))
                else:
                    colors = plt.cm.tab10(np.linspace(0, 1, n_colors))
                return colors
            except Exception as e:
                return plt.cm.tab10(np.linspace(0, 1, n_colors))

        try:
            # Get residuals and fitted values
            fitted = model_results.fittedvalues
            resid = model_results.resid
    
            # Convert to numpy arrays if they aren't already
            fitted = np.array(fitted) if hasattr(fitted, 'values') else fitted
            resid = np.array(resid) if hasattr(resid, 'values') else resid
    
            print(f"Fitted values: {len(fitted)}, Residuals: {len(resid)}")
    
            if len(fitted) == 0 or len(resid) == 0:
                print("No residuals or fitted values available")
                return None

            # Create figure with 2x2 subplots
            fig, axes = plt.subplots(2, 2, figsize=(14, 12))
    
            # Determine analysis type for title
            analysis_type = getattr(self, 'current_analysis_type', 'LMM')
            fig.suptitle(f'{analysis_type} Diagnostic Plots - {metric}', fontsize=16, fontweight='bold')

            # 1. Residuals vs Fitted
            ax1 = axes[0, 0]
            ax1.scatter(fitted, resid, alpha=0.6, s=30, color=get_palette_colors(1)[0])
            ax1.axhline(0, color='red', linestyle='--', linewidth=2)
            ax1.set_xlabel('Fitted Values')
            ax1.set_ylabel('Residuals')
            ax1.set_title('Residuals vs Fitted')
            ax1.grid(True, alpha=0.3)

            # Add LOWESS smoothing line if enough data
            if len(fitted) > 10:
                try:
                    from statsmodels.nonparametric.smoothers_lowess import lowess
                    lowess_result = lowess(resid, fitted, frac=0.6, it=3)
                    ax1.plot(lowess_result[:, 0], lowess_result[:, 1], 
                            color='blue', linewidth=2, label='LOWESS')
                    ax1.legend()
                except Exception as e:
                    print(f"Could not add LOWESS line: {e}")

            # 2. Q-Q Plot
            ax2 = axes[0, 1]
            stats.probplot(resid, dist='norm', plot=ax2)
            ax2.set_title('Q-Q Plot of Residuals')
            ax2.grid(True, alpha=0.3)

            # Add Shapiro-Wilk p-value annotation
            if len(resid) >= 3 and len(resid) <= 5000:
                try:
                    shapiro_stat, shapiro_p = stats.shapiro(resid)
                    ax2.annotate(f'Shapiro-Wilk p = {shapiro_p:.4f}',
                                xy=(0.05, 0.95), xycoords='axes fraction',
                                fontsize=10, bbox=dict(boxstyle='round', facecolor='white', alpha=0.8))
                    if shapiro_p < 0.05:
                        ax2.annotate(' Residuals deviate from normality',
                                    xy=(0.05, 0.88), xycoords='axes fraction',
                                    fontsize=10, color='red')
                except Exception as e:
                    print(f"Shapiro-Wilk test failed: {e}")

            # 3. Residuals by Time
            ax3 = axes[1, 0]
            if lmm_df is not None and 'Time' in lmm_df.columns:
                # Create boxplot of residuals by time
                time_col = lmm_df['Time']
                resid_array = np.array(resid)
        
                # Group residuals by time point
                time_points = sorted(time_col.unique())
                resid_by_time = {}
        
                for time_point in time_points:
                    mask = time_col == time_point
                    if mask.any():
                        try:
                            time_resid = resid_array[mask.values] if hasattr(mask, 'values') else resid[mask]
                            if len(time_resid) > 0:
                                resid_by_time[time_point] = time_resid
                        except:
                            time_resid = resid[mask]
                            if len(time_resid) > 0:
                                resid_by_time[time_point] = time_resid
        
                if resid_by_time:
                    data_for_box = [resid_by_time[t] for t in time_points if t in resid_by_time and len(resid_by_time[t]) > 0]
                    valid_time_points = [t for t in time_points if t in resid_by_time and len(resid_by_time[t]) > 0]
            
                    if data_for_box:
                        bp = ax3.boxplot(data_for_box, positions=range(1, len(valid_time_points)+1),
                                         patch_artist=True, showmeans=True)
                
                        time_colors = get_palette_colors(len(valid_time_points))
                        for i, box in enumerate(bp['boxes']):
                            box.set_facecolor(time_colors[i % len(time_colors)])
                            box.set_alpha(0.7)
                
                        ax3.set_xticks(range(1, len(valid_time_points)+1))
                        ax3.set_xticklabels([f'{int(t)}' for t in valid_time_points], rotation=45, ha='right')
                        ax3.set_xlabel('Time (minutes)')
                        ax3.set_ylabel('Residuals')
                        ax3.set_title('Residuals by Time')
                        ax3.axhline(0, color='red', linestyle='--', linewidth=1, alpha=0.5)
                        ax3.grid(True, alpha=0.3)
                else:
                    ax3.text(0.5, 0.5, 'Not enough data per time point', ha='center', va='center')
                    ax3.set_title('Residuals by Time - Insufficient Data')
            else:
                ax3.text(0.5, 0.5, 'Time column not found', ha='center', va='center')
                ax3.set_title('Residuals by Time - Not Available')

            # 4. Residuals by Line (Channel)
            ax4 = axes[1, 1]
            if lmm_df is not None and 'Line' in lmm_df.columns:
                lines = sorted(lmm_df['Line'].unique())
                resid_by_line = {}
                resid_array = np.array(resid)
        
                for line in lines:
                    mask = lmm_df['Line'] == line
                    if mask.any():
                        try:
                            line_resid = resid_array[mask.values] if hasattr(mask, 'values') else resid[mask]
                            if len(line_resid) > 0:
                                resid_by_line[line] = line_resid
                        except:
                            line_resid = resid[mask]
                            if len(line_resid) > 0:
                                resid_by_line[line] = line_resid
        
                if resid_by_line:
                    data_for_box = [resid_by_line[line] for line in lines if line in resid_by_line and len(resid_by_line[line]) > 0]
                    valid_lines = [line for line in lines if line in resid_by_line and len(resid_by_line[line]) > 0]
            
                    if data_for_box:
                        bp = ax4.boxplot(data_for_box, positions=range(1, len(valid_lines)+1),
                                         patch_artist=True, showmeans=True)
                
                        line_colors = get_palette_colors(len(valid_lines))
                        for i, box in enumerate(bp['boxes']):
                            box.set_facecolor(line_colors[i % len(line_colors)])
                            box.set_alpha(0.7)
                
                        ax4.set_xticks(range(1, len(valid_lines)+1))
                        ax4.set_xticklabels(valid_lines, rotation=45, ha='right')
                        ax4.set_xlabel('Line (Channel)')
                        ax4.set_ylabel('Residuals')
                        ax4.set_title('Residuals by Line')
                        ax4.axhline(0, color='red', linestyle='--', linewidth=1, alpha=0.5)
                        ax4.grid(True, alpha=0.3)
                else:
                    ax4.text(0.5, 0.5, 'Not enough data per line', ha='center', va='center')
                    ax4.set_title('Residuals by Line - Insufficient Data')
            else:
                ax4.text(0.5, 0.5, 'Line column not found', ha='center', va='center')
                ax4.set_title('Residuals by Line - Not Available')

            plt.tight_layout()
            plt.subplots_adjust(top=0.93)
    
            return fig

        except Exception as e:
            print(f"Error generating diagnostic plots: {e}")
            traceback.print_exc()
            return None

    def setup_text_copy_menu(self, text_widget):
        """Add right-click context menu and keyboard shortcuts for Text widget copying"""
        # Create context menu with ONLY Copy and Select All
        menu = tk.Menu(text_widget, tearoff=0)
        menu.add_command(label="Copy", command=lambda: self.copy_text_selection(text_widget))
        menu.add_separator()
        menu.add_command(label="Select All", command=lambda: text_widget.tag_add("sel", "1.0", "end-1c"))
    
        def show_menu(event):
            try:
                menu.tk_popup(event.x_root, event.y_root)
            finally:
                menu.grab_release()
    
        def dismiss_menu(event):
            """Dismiss the menu on left click"""
            try:
                menu.unpost()
            except:
                pass
    
        # Bind right-click to show menu
        text_widget.bind("<Button-3>", show_menu)
        # Bind left-click to dismiss menu
        text_widget.bind("<Button-1>", dismiss_menu)
    
        # Keyboard shortcuts
        text_widget.bind("<Control-c>", lambda e: self.copy_text_selection(text_widget))
        text_widget.bind("<Control-a>", lambda e: text_widget.tag_add("sel", "1.0", "end-1c"))
        text_widget.bind("<Control-A>", lambda e: text_widget.tag_add("sel", "1.0", "end-1c"))
    
        # Store menu reference
        if not hasattr(self, '_text_menus'):
            self._text_menus = []
        self._text_menus.append(menu)
    
        return menu

    def copy_text_selection(self, text_widget):
        """Copy selected text from a Text widget to clipboard"""
        try:
            # Try to get selected text
            selected = text_widget.selection_get()
            if selected:
                self.root.clipboard_clear()
                self.root.clipboard_append(selected)
                self.root.update()
            
                # Show success message
                if hasattr(self, 'slider_info_label'):
                    self.slider_info_label.config(
                        text="Text copied to clipboard", 
                        foreground="green"
                    )
                    self.root.after(2000, lambda: 
                        self.slider_info_label.config(
                            text="Enter values, then click 'Apply Changes'", 
                            foreground="blue"
                        ) if hasattr(self, 'slider_info_label') else None
                    )
            
                return True
            else:
                # No text selected - show message
                if hasattr(self, 'slider_info_label'):
                    self.slider_info_label.config(
                        text="No text selected to copy", 
                        foreground="orange"
                    )
                    self.root.after(2000, lambda: 
                        self.slider_info_label.config(
                            text="Enter values, then click 'Apply Changes'", 
                            foreground="blue"
                        ) if hasattr(self, 'slider_info_label') else None
                    )
                return False
        except tk.TclError:
            # No text selected
            if hasattr(self, 'slider_info_label'):
                self.slider_info_label.config(
                    text="No text selected to copy", 
                    foreground="orange"
                )
                self.root.after(2000, lambda: 
                    self.slider_info_label.config(
                        text="Enter values, then click 'Apply Changes'", 
                        foreground="blue"
                    ) if hasattr(self, 'slider_info_label') else None
                )
            return False

    def copy_text_all(self, text_widget):
        """Copy all text from a Text widget to clipboard"""
        try:
            # Get all text
            all_text = text_widget.get("1.0", tk.END)
            if all_text.strip():
                self.root.clipboard_clear()
                self.root.clipboard_append(all_text)
                self.root.update()
            
                # Show success message
                if hasattr(self, 'slider_info_label'):
                    self.slider_info_label.config(
                        text=" All text copied to clipboard", 
                        foreground="green"
                    )
                    self.root.after(2000, lambda: 
                        self.slider_info_label.config(
                            text="Enter values, then click 'Apply Changes'", 
                            foreground="blue"
                        ) if hasattr(self, 'slider_info_label') else None
                    )
                return True
            return False
        except Exception as e:
            print(f"Error copying all text: {e}")
            return False
    
