    def show_wuei_dist_placeholder_message(self):
        """Show placeholder message in WUEi distribution tab before batch processing"""
        for widget in self.wuei_dist_scrollable_frame.winfo_children():
            widget.destroy()
    
        # Create the plot container for later use
        main_container = ttk.Frame(self.wuei_dist_scrollable_frame)
        main_container.pack(fill=tk.BOTH, expand=True, pady=5)
    
        self.plot_container_in_anova = ttk.Frame(main_container)
        self.plot_container_in_anova.pack(fill=tk.BOTH, expand=True, pady=5)
    
        # Simple placeholder message - no extra buttons
        ttk.Label(self.plot_container_in_anova, 
                 text="Run batch processing to generate WUEi distribution plot\n\n"
                      "Click 'Process Batch' after selecting your files.",
                 font=("Arial", 12), foreground="gray", justify=tk.CENTER).pack(pady=50, expand=True)

